const plannerDefaults={province:'广东',pvKw:1000,storageKw:250,storageKwh:500,dod:90,efficiency:88,reserve:0,pvCost:3000,storageCost:850,siteCost:100000,pvOm:1,storageOm:1.5,annualFixed:10000,days:330,years:20,discount:8,pvDegrade:.5,storageDegrade:2,replaceYear:11,replacePct:60,exportLimit:500,mechanismConfirmed:false,mechanismPct:0,mechanismPrice:.35,referencePrice:.30,mechanismYears:10,extrasConfirmed:false,responseAnnual:0,demandAnnual:0,sourceNote:'演示输入，请替换实际合同与项目数据',
 load:[180,170,160,160,170,180,200,280,380,450,450,420,350,380,440,480,500,480,420,350,280,240,210,190],
 solar:[0,0,0,0,0,0,.02,.10,.25,.45,.65,.78,.85,.78,.65,.45,.25,.10,.02,0,0,0,0,0],
 buy:[.32,.32,.32,.32,.32,.32,.6,.6,.95,.95,.95,.6,.6,.6,.6,.95,.95,.95,.95,.95,.6,.6,.6,.32],
 sell:Array(24).fill(.30)};
let plannerDraft=structuredClone(plannerDefaults),plannerResult=null;
try{const saved=JSON.parse(localStorage.getItem('power-planner-v1')||'null');if(saved){PlannerEngine.validate(saved);if(plannerPolicies[saved.province])plannerDraft={...saved};}}catch{}
const escapePlan=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const planMoney=v=>`${fmt(v/10000)} 万元`;
function planField(id,label,min=0,max=1e9,step='any'){return `<label>${label}<input name="${id}" type="number" value="${plannerDraft[id]}" min="${min}" max="${max}" step="${step}" required></label>`;}
function planner(){app.innerHTML=heading('储能与光伏盈利规划','用同一组项目数据，比较设备组合、运营收益与投资现金流。','ENERGY BUSINESS PLANNER')+`<div class="notice"><strong>用户侧工商业 · 方案预评估</strong><br>首批覆盖山东、山西、广东、浙江、江苏、蒙西的规则阅读与条件核对。所有负荷、电价、成本默认值均为演示假设；切换地区不会自动套用电价。测算为税前、无融资的项目整体现金流，不等同于各省交易系统结算或可研结论。</div><form id="plannerForm"><section class="panel"><div class="section-head"><h2>01 / 地区与收益边界</h2><span class="tag">资料核对：2026-10-04</span></div><div class="plan-top"><label>项目所在地区<select name="province">${Object.keys(plannerPolicies).map(p=>`<option ${p===plannerDraft.province?'selected':''}>${p}</option>`).join('')}</select></label><label>电价 / 项目参数的来源说明<input name="sourceNote" maxlength="200" value="${escapePlan(plannerDraft.sourceNote)}" placeholder="合同名称、价格月份、项目报价或演示假设"></label></div><div id="policyCard"></div></section><div class="plan-input-grid"><section class="panel"><div class="section-head"><h2>02 / 光伏、储能与运行条件</h2></div><div class="fields">${planField('pvKw','光伏装机（kW）',0,1000000)}${planField('storageKw','储能交流功率（kW）',0,1000000)}${planField('storageKwh','储能额定容量（kWh）',0,10000000)}${planField('dod','可用容量 / DoD（%）',1,100)}${planField('efficiency','交流往返效率（%）',1,100)}${planField('reserve','专用资源预留比例（%）',0,95)}${planField('exportLimit','光伏上网功率上限（kW）',0,1000000)}${planField('days','典型日代表天数 / 年',1,365,1)}</div><p class="subtitle">预留比例同时减少套利可用功率与容量。储能仅向本地负荷放电，不向电网售电；余电上网限制只作用于光伏。</p></section><section class="panel"><div class="section-head"><h2>03 / 投资与全周期成本</h2></div><div class="fields">${planField('pvCost','光伏完整投资（元/kW）',0,100000)}${planField('storageCost','储能完整投资，含 PCS（元/kWh）',0,100000)}${planField('siteCost','接网 / 场地等一次投入（元）',0,1e10)}${planField('pvOm','光伏年运维 / 原投资（%）',0,100)}${planField('storageOm','储能年运维 / 原投资（%）',0,100)}${planField('annualFixed','项目年固定费用（元）',0,1e9)}${planField('years','评估年限（年）',1,30,1)}${planField('discount','折现率（%）',0,50)}${planField('pvDegrade','光伏年衰减（%）',0,30)}${planField('storageDegrade','储能年容量衰减（%）',0,30)}${planField('replaceYear','储能更换年份，0 为不更换',0,30,1)}${planField('replacePct','更换成本 / 原储能投资（%）',0,200)}</div></section></div><section class="panel"><div class="section-head"><h2>04 / 典型日逐时曲线</h2><button type="button" class="text-link" id="resetCurves">恢复演示曲线</button></div><p class="subtitle">每列填写 24 个数，以逗号、空格或换行分隔，按 00:00–23:00 顺序。价格单位为元/kWh，勿直接填元/MWh。光伏出力填写每 kW 装机的小时平均 kW（0–1）。</p><div class="plan-curves">${[['load','负荷（kW）'],['solar','光伏归一化出力（kW/kW）'],['buy','可避免的购电单价（元/kWh）'],['sell','光伏余电上网单价（元/kWh）']].map(([id,title])=>`<label>${title}<textarea name="${id}" rows="5" required>${plannerDraft[id].join(', ')}</textarea></label>`).join('')}</div><p class="subtitle">购电单价只填随用电量减少而可避免的费用；固定基本电费不混入。现货套餐应输入合同映射后的边际结算单价。模型允许负电价，并假设有权弃光；必须上网的项目不适用该弃光假设。</p></section><details class="panel plan-optional"><summary>05 / 有条件的收益：机制差价、需求响应与基本电费节省</summary><div class="notice" style="margin-top:18px">默认不计入。填写后仍须勾选资格确认；容量电价、辅助服务、绿证及补贴不自动叠加。机制差价只按实际光伏上网电量计入，未模拟逐月清算。</div><label class="checkbox-label"><input type="checkbox" name="mechanismConfirmed" ${plannerDraft.mechanismConfirmed?'checked':''}> 已核实当前项目的机制资格、覆盖电量比例与剩余执行期限</label><div class="fields">${planField('mechanismPct','实际上网电量的机制覆盖（%）',0,100)}${planField('mechanismPrice','已确认机制电价（元/kWh）',-10,10)}${planField('referencePrice','机制结算参考均价（元/kWh）',-10,10)}${planField('mechanismYears','剩余机制执行年限',0,30,1)}</div><label class="checkbox-label"><input type="checkbox" name="extrasConfirmed" ${plannerDraft.extrasConfirmed?'checked':''}> 已核实附加净收益与计费依据，且扣除重复贡献、履约和交易成本</label><div class="fields">${planField('responseAnnual','已确认需求响应年净收入（元）',0,1e9)}${planField('demandAnnual','已确认基本电费年净节省（元）',0,1e9)}</div><p class="subtitle">需求响应必须设置专用预留比例。基本电费节省需另用月度最大需量、计费方式与历史账单核实，本模型不会根据一个典型日自动生成该收入。两项只进入含储能方案，并假设评估期内持续有效。</p></details><div class="plan-actions"><button class="primary dark" type="submit">计算并比较四种方案 ↗</button><button class="secondary" type="button" id="savePlan">保存本机参数</button><button class="secondary" type="button" id="exportPlan">导出方案与结果</button><span id="planStatus" role="status"></span></div></form><div id="plannerOutput"></div>`;renderPolicy();const form=document.getElementById('plannerForm');form.elements.province.addEventListener('change',()=>{plannerDraft.province=form.elements.province.value;form.elements.mechanismConfirmed.checked=false;form.elements.extrasConfirmed.checked=false;renderPolicy();document.getElementById('plannerOutput').innerHTML='';plannerResult=null;document.getElementById('planStatus').textContent='地区已变更，收益资格确认已重置；请核对价格后重新计算。'});form.addEventListener('input',e=>{if(e.target.name!=='province'){document.getElementById('planStatus').textContent='参数已修改，请重新计算。';plannerResult=null;document.getElementById('plannerOutput').innerHTML='';}});form.onsubmit=e=>{e.preventDefault();computePlan()};document.getElementById('resetCurves').onclick=()=>{for(const k of ['load','solar','buy','sell'])form.elements[k].value=plannerDefaults[k].join(', ');plannerResult=null;document.getElementById('plannerOutput').innerHTML='';document.getElementById('planStatus').textContent='已恢复演示曲线，请重新计算。'};document.getElementById('savePlan').onclick=()=>{try{plannerDraft=readPlan();localStorage.setItem('power-planner-v1',JSON.stringify(plannerDraft));document.getElementById('planStatus').textContent='参数已保存到当前浏览器。'}catch(e){document.getElementById('planStatus').textContent=e.message}};document.getElementById('exportPlan').onclick=exportPlan;computePlan();}
function renderPolicy(){const p=plannerPolicies[plannerDraft.province];document.getElementById('policyCard').innerHTML=`<div class="policy-card"><div><strong>${plannerDraft.province} / ${p.focus}</strong><span class="pill">条件核对 · 非自动资格认定</span></div><ul>${p.notes.map(n=>`<li>${n}</li>`).join('')}</ul><div class="policy-links">${p.sources.concat(plannerNationalSources).map(([t,u])=>`<a href="${u}" target="_blank" rel="noopener">${t} ↗</a>`).join('')}</div></div>`;}
function readPlan(){const form=document.getElementById('plannerForm');if(!form.reportValidity())throw Error('请修正输入范围与必填项目');const p={};for(const k of Object.keys(plannerDefaults)){const e=form.elements[k];if(['load','solar','buy','sell'].includes(k))p[k]=e.value.trim().split(/[\s,，;；]+/).map(Number);else if(['province','sourceNote'].includes(k))p[k]=e.value.trim();else if(['mechanismConfirmed','extrasConfirmed'].includes(k))p[k]=e.checked;else p[k]=Number(e.value);}if(!plannerPolicies[p.province])throw Error('不支持的地区');return PlannerEngine.validate(p);}
function computePlan(){try{const p=readPlan();document.getElementById('planStatus').textContent='正在计算…';plannerDraft=p;const results=['baseline','pv','storage','combo'].map(mode=>PlannerEngine.evaluate(p,mode));plannerResult={params:structuredClone(p),results};renderPlanResults(results,p);document.getElementById('planStatus').textContent='已完成四方案比较。结果基于当前输入假设。';}catch(e){document.getElementById('planStatus').textContent=e.message;document.getElementById('plannerOutput').innerHTML='';plannerResult=null;}}
function planTable(headers,rows){return `<div class="plan-table-wrap"><table class="plan-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function planChart(series,labels,unit){const w=760,h=220,pad=45,values=series.flatMap(s=>s.data),min=Math.min(0,...values),max=Math.max(1,...values),range=max-min;const x=i=>pad+i/(labels.length-1)*(w-pad-15),y=v=>h-pad-(v-min)/range*(h-pad-20);return `<div class="plan-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${escapePlan(unit)}趋势图">${[0,.5,1].map(f=>{const v=min+f*range;return `<line x1="${pad}" x2="${w-15}" y1="${y(v)}" y2="${y(v)}" stroke="#dfe5d8"/><text x="${pad-5}" y="${y(v)+4}" text-anchor="end" fill="#80917d" font-size="10">${fmt(v)}</text>`}).join('')}${series.map(s=>`<polyline points="${s.data.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}" fill="none" stroke="${s.color}" stroke-width="2.5"/>`).join('')}${labels.map((l,i)=>i===0||i===labels.length-1||i%Math.max(1,Math.floor(labels.length/6))===0?`<text x="${x(i)}" y="${h-17}" text-anchor="middle" fill="#80917d" font-size="10">${l}</text>`:'').join('')}<text x="${pad}" y="12" fill="#80917d" font-size="10">${unit}</text></svg><div class="chart-legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${s.label}</span>`).join('')}</div></div>`;}
function renderPlanResults(results,p){const names={baseline:'不建设',pv:'仅光伏',storage:'仅储能',combo:'光伏＋储能'},combo=results[3],pv=results[1],r=combo.rows[0];const best=results.reduce((a,b)=>b.npv>a.npv?b:a),marginalNpv=combo.npv-pv.npv;const displayIrr=x=>x.irr===null?'无唯一有效值':fmt(x.irr*100)+'%';const cumulative=[];let c=-combo.capex;cumulative.push(c/10000);combo.rows.forEach(row=>{c+=row.cash;cumulative.push(c/10000)});
 document.getElementById('plannerOutput').innerHTML=`<section class="panel plan-result"><div class="section-head"><div><h2>方案比较 / ${escapePlan(p.province)}</h2><p>输入来源：${escapePlan(p.sourceNote||'未填写来源')}</p></div><span class="tag">税前项目现金流 · 典型日外推</span></div><div class="notice"><strong>${best.mode==='baseline'?'当前假设下，各建设方案 NPV 均不优于不建设。':`当前假设下，${names[best.mode]}的 NPV 最高。`}</strong><br>这是所列四种配置的比较，未进行所有容量的全局寻优或融资测算。光储组合相对仅光伏的增量 NPV 为 ${planMoney(marginalNpv)}；判断是否加储能应关注该增量，而不能把光伏收益全部归给储能。</div><div class="stats"><div class="stat"><div><small>光储组合初始投入</small><b>${fmt(combo.capex/10000)}<span>万元</span></b></div></div><div class="stat"><div><small>光储组合首年净现金流</small><b>${fmt(r.cash/10000)}<span>万元</span></b></div></div><div class="stat"><div><small>光储组合 NPV</small><b>${fmt(combo.npv/10000)}<span>万元</span></b></div></div></div>${planTable(['方案','初始投入（万元）','首年净现金流（万元）','NPV（万元）','IRR','首次静态回收'],results.map(x=>[names[x.mode],fmt(x.capex/10000),fmt(x.rows[0].cash/10000),fmt(x.npv/10000),displayIrr(x),x.capex===0?'不适用':x.payback===null?'评估期内未回收':fmt(x.payback)+' 年']))}<p class="subtitle">IRR 在现金流多次变号或求解范围内无根时不提供单一值；优先比较 NPV。首次回收不保证后续更换设备后累计现金仍为正。</p></section><div class="plan-input-grid"><section class="panel"><div class="section-head"><h2>光储组合 / 首年收益账本</h2></div>${planTable(['项目','首年金额（万元）'],[['可避免的购电费用节省',fmt(r.savings/10000)],['光伏余电售电收入',fmt(r.exports/10000)],['已确认机制差价（可为负）',fmt(r.mechanism/10000)],['已确认附加净收益',fmt(r.extra/10000)],['运维与固定费用',fmt(-r.om/10000)],['储能更换支出',fmt(-r.replacement/10000)],['首年净现金流',fmt(r.cash/10000)]])}<div class="formula">组合电能量价值 = 光伏单独运行价值 ${planMoney(combo.pvReference)} + 加储能的净增量 ${planMoney(combo.storageIncrement)}</div><p class="subtitle">储能增量已经扣除充电成本、损耗和减少余电上网的机会成本，不能再加一次“峰谷套利收益”。</p></section><section class="panel"><div class="section-head"><h2>盈利模式设计</h2></div><div class="business-card"><strong>自投自用 / 当前计算口径</strong><p>项目整体承担投资和运维，获取购电节省与余电收入；收益权和设备所有权应保持清晰。</p></div><div class="business-card"><strong>合同能源管理 / 分成设计</strong><p>先以组合收益为基数，约定业主与投资方的节省分成、上网收入归属和响应收益归属；另建双方现金流后再评估，当前 IRR 不能直接代表投资方 IRR。</p></div><div class="business-card"><strong>租赁或聚合运营 / 条件式收益</strong><p>租金、聚合服务费、保底与偏差责任需进入合同；参加需求响应、辅助服务需核对计量、通信和履约条件，并预留资源。</p></div><p class="subtitle">电网侧独立储能、绿电直连与辅助服务报价属于不同项目边界，尚未作为自动收益方案实现。</p></section></div><section class="panel"><div class="section-head"><h2>光储组合 / 首年典型日调度</h2><span class="tag">60 个容量步长 · 已知曲线的理想调度</span></div>${planChart([{label:'原负荷',color:'#9aa98e',data:p.load},{label:'光伏出力',color:'#c6a444',data:combo.first.hours.map(h=>h.pv)},{label:'购网功率',color:'#1b6455',data:combo.first.hours.map(h=>h.importKwh)}],Array.from({length:24},(_,i)=>`${i}时`),'kW / 1小时时段')}<div class="notice">日初与日末均处于预留 SOC 下限，充放电互斥且遵守功率、容量、效率与本地负荷限制。可用 SOC 不含预留电量。约 ${fmt(combo.cycles)} 次等效日循环；该结果未加入循环寿命硬约束。调度采用完整曲线预知，现实预测误差可能降低收益。</div><details><summary>查看逐时能量账（kWh）</summary>${planTable(['时段','负荷','光伏','购网','余电上网','电网充电','光伏充电','放电','可用 SOC','弃光'],combo.first.hours.map(h=>[h.h+':00',h.load,h.pv,h.importKwh,h.exportKwh,h.gridCharge,h.pvCharge,h.discharge,h.soc,h.curtail].map((v,i)=>i?fmt(v):v)))}</details><p class="subtitle">年光伏产量 ${fmt(combo.first.pv*p.days/1000)} MWh；年光伏充电量 ${fmt(combo.first.pvCharge*p.days/1000)} MWh；年余电上网 ${fmt(combo.first.exportKwh*p.days/1000)} MWh。光伏充电量不直接等于最终自用电量，需扣除储能损耗。</p></section><section class="panel"><div class="section-head"><h2>全周期现金流 / 光储组合</h2></div>${planChart([{label:'累计未折现现金流',color:'#1b6455',data:cumulative}],Array.from({length:p.years+1},(_,i)=>`${i}年`),'万元')}<details><summary>查看逐年现金流</summary>${planTable(['年度','购电节省','余电收入','机制差价','附加净收益','运维支出','更换支出','净现金流（万元）'],combo.rows.map(row=>[row.year,...['savings','exports','mechanism','extra','om','replacement','cash'].map(k=>fmt(row[k]/10000))]))}</details></section><section class="panel"><div class="section-head"><h2>电价差与设备成本敏感性</h2></div><div id="sensitivity"></div></section><section class="panel"><div class="section-head"><h2>落地前需要补齐的数据</h2></div><p class="subtitle">① 各月工作日、非工作日与光伏曲线，建议实测 15 分钟数据；本版仅将一个典型日重复 ${p.days} 天，其余天不计能量收益。<br>② 适用零售合同、上网结算路径、月份电价、并网功率与购网容量，当前未建模变压器购网功率限制。<br>③ 屋顶与接入条件、消防安全、完整设备报价、可用年限和循环质保；当前未计建设期、税费、融资、残值和退役成本。<br>④ 机制资格、剩余年限、月度清算、响应履约与最大需量计费，需分别核验；当前模型不是省级结算合规引擎。</p></section>`;
 const avg=p.buy.reduce((a,b)=>a+b,0)/24;const sensitivity=[['基础场景',1,1],['分时价差收窄 20%',.8,1],['分时价差扩大 20%',1.2,1],['设备投资增加 20%',1,1.2]].map(([label,spread,cost])=>{const q={...p,buy:p.buy.map(v=>avg+(v-avg)*spread),pvCost:p.pvCost*cost,storageCost:p.storageCost*cost};try{const x=PlannerEngine.evaluate(q,'combo');return [label,fmt(x.rows[0].cash/10000),fmt(x.npv/10000),x.payback===null?'未回收':fmt(x.payback)+' 年']}catch{return [label,'场景参数超出模型范围','—','—']}});document.getElementById('sensitivity').innerHTML=planTable(['场景','首年现金流（万元）','NPV（万元）','首次回收'],sensitivity)+`<p class="subtitle">价差场景保持购电价格的算术均值，上网价格不变；其余参数保持输入值。此处为假设敏感性，不是价格预测。</p>`;
}
function exportPlan(){try{const p=readPlan();if(!plannerResult||JSON.stringify(p)!==JSON.stringify(plannerResult.params))throw Error('请先按最新参数计算，再导出结果');const report={format:'power-market-planner-v1',generatedAt:new Date().toISOString(),province:p.province,assumptions:p,sources:plannerPolicies[p.province].sources.concat(plannerNationalSources),scope:'用户侧工商业、税前无融资、典型日外推、逐时60步长、非省级结算引擎',results:plannerResult.results};const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`光储规划-${p.province}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('planStatus').textContent='已导出参数、官方来源、逐时调度和现金流。';}catch(e){document.getElementById('planStatus').textContent=e.message}}
